CREATE TABLE IF NOT EXISTS story_artifacts (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  artifact_code varchar(3) NOT NULL,
  title varchar(120) NOT NULL,
  description text NOT NULL,
  image_path text NOT NULL,
  semantic_tags jsonb NOT NULL DEFAULT '[]'::jsonb,
  scenario_affinities jsonb NOT NULL DEFAULT '[]'::jsonb,
  description_embedding jsonb,
  embedding_model varchar(80),
  is_active boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE story_artifacts
  ADD COLUMN IF NOT EXISTS semantic_tags jsonb NOT NULL DEFAULT '[]'::jsonb,
  ADD COLUMN IF NOT EXISTS scenario_affinities jsonb NOT NULL DEFAULT '[]'::jsonb,
  ADD COLUMN IF NOT EXISTS description_embedding jsonb,
  ADD COLUMN IF NOT EXISTS embedding_model varchar(80);

ALTER TABLE stories
  ADD COLUMN IF NOT EXISTS closing_artifact_id uuid REFERENCES story_artifacts(id) ON DELETE SET NULL;

CREATE UNIQUE INDEX IF NOT EXISTS story_artifacts_artifact_code_uidx
  ON story_artifacts(artifact_code);

CREATE INDEX IF NOT EXISTS story_artifacts_active_idx
  ON story_artifacts(is_active);

CREATE INDEX IF NOT EXISTS story_artifacts_scenario_affinities_idx
  ON story_artifacts USING gin (scenario_affinities);

CREATE INDEX IF NOT EXISTS story_artifacts_semantic_tags_idx
  ON story_artifacts USING gin (semantic_tags);

CREATE INDEX IF NOT EXISTS story_artifacts_search_ru_idx
  ON story_artifacts USING gin (
    to_tsvector('russian', coalesce(title, '') || ' ' || coalesce(description, ''))
  );

CREATE INDEX IF NOT EXISTS stories_closing_artifact_id_idx
  ON stories(closing_artifact_id);

ON CONFLICT (artifact_code) DO UPDATE SET
  title = EXCLUDED.title,
  description = EXCLUDED.description,
  image_path = EXCLUDED.image_path,
  semantic_tags = EXCLUDED.semantic_tags,
  scenario_affinities = EXCLUDED.scenario_affinities,
  is_active = true,
  updated_at = now();
